style.css:
@-moz-document domain("youtube.com") {
html, body, ytd-app {
        background-color: #000000 !important;
        background-image: url('https://unsplash.com') !important;
        background-attachment: fixed !important;
        background-size: cover !important;
        background-position: center !important;
    }
    ytd-watch-flexy, ytd-page-manager, ytd-browse, #contentContainer, #page-manager {
        background: transparent !important;
    }
    yt-formatted-string, span, h1, h2, h3, #video-title, .title.ytd-video-primary-info-renderer {
        color: #ffffff !important;
    }
    #metadata-line span, #byline, .channel-name {
        color: #aaaaaa !important;
    }
    yt-icon, .yt-spec-icon-shape {
        color: #ffffff !important;
    }
    ytd-guide-renderer, ytd-mini-guide-renderer, #masthead-container, #background.ytd-masthead {
        background: rgba(0, 0, 0, 0.85) !important;
        backdrop-filter: blur(10px) !important;
    }
    ytd-rich-grid-media:hover, ytd-compact-video-renderer:hover {
        box-shadow: 0 0 15px rgba(154, 46, 254, 0.4) !important;
        transition: box-shadow 0.3s ease-in-out;
    }
}
